              "curl": "curl -X PATCH \"https://api.nextmoe.dev/v2/me/news/value\" \\\n  -H \"Authorization: Bearer <ACCESS_TOKEN>\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{}'"
